package com.example.customerrouting.agent;
import com.example.customerrouting.skill.Skill; import jakarta.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="agents") public class Agent { @Id private UUID id=UUID.randomUUID(); @Column(nullable=false) private String name; @Enumerated(EnumType.STRING) private AgentStatus status=AgentStatus.ONLINE; private int maxCapacity; private int activeEnquiryCount; private Instant lastAssignedAt; private Instant lastHeartbeatAt; private Instant createdAt=Instant.now(); @Version private Long version;
 @ElementCollection(targetClass=Language.class) @Enumerated(EnumType.STRING) @CollectionTable(name="agent_languages") private Set<Language> languages=new HashSet<>(); @ManyToMany(fetch=FetchType.EAGER) @JoinTable(name="agent_skills") private Set<Skill> skills=new HashSet<>(); protected Agent(){} public Agent(String n,Set<Language> l,Set<Skill>s,int c){name=n;languages=l;skills=s;maxCapacity=c;}
 public UUID getId(){return id;} public String getName(){return name;} public AgentStatus getStatus(){return status;} public int getMaxCapacity(){return maxCapacity;} public int getActiveEnquiryCount(){return activeEnquiryCount;} public Instant getLastAssignedAt(){return lastAssignedAt;} public Instant getLastHeartbeatAt(){return lastHeartbeatAt;} public Set<Language> getLanguages(){return languages;} public Set<Skill> getSkills(){return skills;} public void setStatus(AgentStatus s){status=s;} public void setMaxCapacity(int c){maxCapacity=c;} public void heartbeat(){lastHeartbeatAt=Instant.now();} public void claim(){activeEnquiryCount++;lastAssignedAt=Instant.now();} public void release(){if(activeEnquiryCount>0)activeEnquiryCount--;} }
